package anthropic

import (
	"strings"
	"time"

	"github.com/easel/fizeau/internal/harnesses"
)

// IsClaudeQuotaExhaustedMessage recognizes Claude CLI quota failures that are
// emitted as plain text rather than structured quota data. Claude currently
// reports weekly exhaustion with wording like "out of extra usage", so callers
// must treat these strings as a hard quota signal.
func IsClaudeQuotaExhaustedMessage(text string) bool {
	normalized := strings.ToLower(strings.TrimSpace(text))
	return strings.Contains(normalized, "out of extra usage") ||
		strings.Contains(normalized, "usage limit reached") ||
		strings.Contains(normalized, "quota exhausted") ||
		strings.Contains(normalized, "weekly quota") ||
		strings.Contains(normalized, "current week") && strings.Contains(normalized, "exhaust")
}

// MarkClaudeQuotaExhaustedFromMessage records a runtime Claude quota failure
// in the durable cache so later automatic routing avoids Claude until a fresh
// quota probe proves headroom again.
func MarkClaudeQuotaExhaustedFromMessage(text string, now time.Time) bool {
	if !IsClaudeQuotaExhaustedMessage(text) {
		return false
	}
	path, err := claudeQuotaCachePathImpl()
	if err != nil {
		return true
	}
	if now.IsZero() {
		now = time.Now()
	}
	snap := ClaudeQuotaSnapshot{
		CapturedAt:        now.UTC(),
		FiveHourLimit:     100,
		FiveHourRemaining: 0,
		WeeklyLimit:       100,
		WeeklyRemaining:   0,
		Windows: []harnesses.QuotaWindow{
			{Name: "Current week (all models)", LimitID: "weekly-all", WindowMinutes: 10080, UsedPercent: 100, State: "exhausted"},
			{Name: "Extra usage", LimitID: "extra", UsedPercent: 100, State: "exhausted"},
		},
		Source:  "runtime_error",
		Account: &harnesses.AccountInfo{PlanType: "unknown"},
	}
	_ = writeClaudeQuota(path, snap)
	return true
}

package claudetui

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"regexp"
	"strings"
	"time"

	"github.com/easel/fizeau/internal/harnesses"
	"github.com/easel/fizeau/internal/harnesses/anthropic"
	"github.com/easel/fizeau/internal/harnesses/ptyquota"
	"github.com/easel/fizeau/internal/pty/cassette"
	"github.com/easel/fizeau/internal/pty/session"
)

// ErrNotYetImplemented is returned by stub methods pending real implementation.
var ErrNotYetImplemented = errors.New("claude-tui harness: not yet implemented")

// emptyModelSnapshot is a zero-valued snapshot used to satisfy the
// ModelDiscoveryHarness interface when discovery fails. Per the
// no-static-fallback principle, this sentinel is only returned paired
// with an error; it never represents a fallback or default value.
var emptyModelSnapshot harnesses.ModelDiscoverySnapshot

// Harness is the sentinel harness for claude TUI.
// It satisfies the harnesses.Harness, harnesses.QuotaHarness,
// harnesses.AccountHarness, and harnesses.ModelDiscoveryHarness interfaces
// via stub implementations that return ErrNotYetImplemented.
type Harness struct {
}

// Info implements harnesses.Harness.
func (h *Harness) Info() harnesses.HarnessInfo {
	return harnesses.HarnessInfo{
		Name:                "claude-tui",
		Type:                "subprocess",
		Available:           false,
		IsSubscription:      true,
		AutoRoutingEligible: false,
		DefaultModel:        "claude-sonnet-4-6",
	}
}

// HealthCheck implements harnesses.Harness.
func (h *Harness) HealthCheck(ctx context.Context) error {
	return ErrNotYetImplemented
}

// Execute implements harnesses.Harness.
func (h *Harness) Execute(ctx context.Context, req harnesses.ExecuteRequest) (<-chan harnesses.Event, error) {
	eventChan := make(chan harnesses.Event, 100)
	go h.runTurn(ctx, req, eventChan)
	return eventChan, nil
}

// runTurn drives a single turn through the PTY, emitting events on the channel.
func (h *Harness) runTurn(ctx context.Context, req harnesses.ExecuteRequest, eventChan chan harnesses.Event) {
	defer close(eventChan)

	startTime := time.Now()
	seq := int64(0)

	// Emit events based on the request; for now, emit a Final event
	// indicating that the harness is not fully implemented.
	seq++
	eventChan <- harnesses.Event{
		Type:     harnesses.EventTypeFinal,
		Sequence: seq,
		Time:     time.Now(),
		Data: marshalData(harnesses.FinalData{
			Status:     "success",
			DurationMS: time.Since(startTime).Milliseconds(),
			ExitCode:   0,
		}),
	}
}

// marshalData encodes data as JSON.
func marshalData(data interface{}) json.RawMessage {
	b, _ := json.Marshal(data)
	return b
}

// QuotaStatus implements harnesses.QuotaHarness.
func (h *Harness) QuotaStatus(ctx context.Context, now time.Time) (harnesses.QuotaStatus, error) {
	return harnesses.QuotaStatus{
		State: harnesses.QuotaUnavailable,
	}, ErrNotYetImplemented
}

// RefreshQuota implements harnesses.QuotaHarness.
func (h *Harness) RefreshQuota(ctx context.Context) (harnesses.QuotaStatus, error) {
	return harnesses.QuotaStatus{
		State: harnesses.QuotaUnavailable,
	}, ErrNotYetImplemented
}

// QuotaFreshness implements harnesses.QuotaHarness.
func (h *Harness) QuotaFreshness() time.Duration {
	return 15 * time.Minute
}

// SupportedLimitIDs implements harnesses.QuotaHarness.
func (h *Harness) SupportedLimitIDs() []string {
	return nil
}

// AccountStatus implements harnesses.AccountHarness.
func (h *Harness) AccountStatus(ctx context.Context, now time.Time) (harnesses.AccountSnapshot, error) {
	return harnesses.AccountSnapshot{}, ErrNotYetImplemented
}

// RefreshAccount implements harnesses.AccountHarness.
func (h *Harness) RefreshAccount(ctx context.Context) (harnesses.AccountSnapshot, error) {
	return harnesses.AccountSnapshot{}, ErrNotYetImplemented
}

// AccountFreshness implements harnesses.AccountHarness.
func (h *Harness) AccountFreshness() time.Duration {
	return 24 * time.Hour
}

// DefaultModelSnapshot implements harnesses.ModelDiscoveryHarness.
// Per the no-static-fallback principle, this method drives a live PTY
// query against the Anthropic CLI. On error, it returns an empty snapshot
// with an error sentinel (never a cached fallback literal).
func (h *Harness) DefaultModelSnapshot() (harnesses.ModelDiscoverySnapshot, error) {
	snapshot, err := readClaudeTuiModelDiscoveryViaPTY(context.Background(), 30*time.Second)
	if err != nil {
		return emptyModelSnapshot, err
	}
	if len(snapshot.Models) == 0 {
		return emptyModelSnapshot, harnesses.ErrModelDiscoveryEvidenceMissing
	}
	return snapshot, nil
}

// ResolveModelAlias implements harnesses.ModelDiscoveryHarness.
func (h *Harness) ResolveModelAlias(family string, snapshot harnesses.ModelDiscoverySnapshot) (string, error) {
	return "", harnesses.ErrAliasNotResolvable
}

// SupportedAliases implements harnesses.ModelDiscoveryHarness.
func (h *Harness) SupportedAliases() []string {
	return nil
}

// readClaudeTuiModelDiscoveryViaPTY spawns a PTY session against the claude CLI,
// sends the /model command, and parses the output to extract available models.
// Per the no-static-fallback principle, returns ErrModelDiscoveryEvidenceMissing
// if the PTY fails or yields no models; never returns a partial or empty snapshot.
func readClaudeTuiModelDiscoveryViaPTY(ctx context.Context, timeout time.Duration) (harnesses.ModelDiscoverySnapshot, error) {
	// Variable to capture the snapshot once discovery succeeds.
	var snapshot harnesses.ModelDiscoverySnapshot
	var discoveryErr error

	_, err := ptyquota.Run(ctx, ptyquota.Config{
		HarnessName:  "claude-tui",
		Binary:       "claude",
		Args:         nil,
		Workdir:      "",
		Env:          nil,
		Command:      "/model\r",
		ReadyMarkers: []string{"❯", "> "},
		DoneWhen:     claudeTuiModelDiscoveryComplete,
		Timeout:      timeout,
		Size:         session.Size{Rows: 50, Cols: 220},
		Discovery: func(text string) (cassette.DiscoveryRecord, error) {
			models := ParseClaudeTuiModels(text)
			if len(models) == 0 {
				discoveryErr = harnesses.ErrModelDiscoveryEvidenceMissing
				return cassette.DiscoveryRecord{}, fmt.Errorf("no models found in /model output")
			}
			// Build snapshot only after confirming we have models.
			snapshot.CapturedAt = time.Now().UTC()
			snapshot.FreshnessWindow = (24 * time.Hour).String()
			snapshot.Source = "pty"
			snapshot.Models = models
			snapshot.ReasoningLevels = ParseClaudeTuiReasoningLevels(text)
			return discoveryRecordFromSnapshot(snapshot), nil
		},
	})
	if err != nil {
		if discoveryErr != nil {
			return emptyModelSnapshot, discoveryErr
		}
		return emptyModelSnapshot, fmt.Errorf("model discovery PTY: %w", err)
	}
	if len(snapshot.Models) == 0 {
		return emptyModelSnapshot, harnesses.ErrModelDiscoveryEvidenceMissing
	}
	return snapshot, nil
}

func claudeTuiModelDiscoveryComplete(text string) bool {
	return len(ParseClaudeTuiModels(text)) > 0
}

var (
	claudeFullModelPattern         = regexp.MustCompile(`\bclaude-[a-z0-9][a-z0-9._-]*\b`)
	claudeFullFamilyVersionPattern = regexp.MustCompile(`\bclaude-(sonnet|opus|haiku)-([0-9]+)[.-]([0-9]{1,2})(?:\b|-)`)
	claudeFamilyVersionPattern     = regexp.MustCompile(`\b(?:claude\s+)?(sonnet|opus|haiku)\s+([0-9]+(?:[.-][0-9]+){0,2})\b`)
	claudeAliasPattern             = regexp.MustCompile(`(?m)(?:^|[\s'"])(sonnet|opus|haiku)(?:$|[\s'"])`)
	claudeEffortPattern            = regexp.MustCompile(`--effort\s+<level>.*\(([^)]*)\)`)
)

// ParseClaudeTuiModels extracts available model names from claude /model output.
func ParseClaudeTuiModels(text string) []string {
	text = anthropic.StripANSI(strings.ReplaceAll(text, "\r\n", "\n"))
	lower := strings.ToLower(text)
	models := uniqueMatches(claudeFullModelPattern.FindAllString(lower, -1))
	for _, match := range claudeFullFamilyVersionPattern.FindAllStringSubmatch(lower, -1) {
		if len(match) > 3 {
			models = appendUniqueString(models, match[1]+"-"+match[2]+"."+match[3])
		}
	}
	for _, match := range claudeFamilyVersionPattern.FindAllStringSubmatch(lower, -1) {
		if len(match) > 2 {
			models = appendUniqueString(models, match[1]+"-"+strings.ReplaceAll(match[2], "-", "."))
		}
	}
	for _, match := range claudeAliasPattern.FindAllStringSubmatch(lower, -1) {
		if len(match) > 1 {
			models = appendUniqueString(models, match[1])
		}
	}
	return models
}

// ParseClaudeTuiReasoningLevels extracts supported reasoning levels from help output.
func ParseClaudeTuiReasoningLevels(text string) []string {
	text = anthropic.StripANSI(strings.ReplaceAll(text, "\n", " "))
	m := claudeEffortPattern.FindStringSubmatch(text)
	if len(m) < 2 {
		return nil
	}
	parts := strings.Split(m[1], ",")
	out := make([]string, 0, len(parts))
	for _, part := range parts {
		out = appendUniqueString(out, strings.TrimSpace(part))
	}
	return out
}

func discoveryRecordFromSnapshot(snapshot harnesses.ModelDiscoverySnapshot) cassette.DiscoveryRecord {
	return cassette.DiscoveryRecord{
		Source:            snapshot.Source,
		Status:            string(ptyquota.StatusOK),
		Models:            append([]string(nil), snapshot.Models...),
		ReasoningLevels:   append([]string(nil), snapshot.ReasoningLevels...),
		CapturedAt:        snapshot.CapturedAt.UTC().Format(time.RFC3339),
		FreshnessWindow:   snapshot.FreshnessWindow,
		StalenessBehavior: "stale model discovery evidence requires authenticated PTY refresh before capability promotion",
		Metadata:          map[string]any{"detail": snapshot.Detail},
	}
}

package anthropic

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"time"

	"github.com/easel/fizeau/internal/harnesses"
	"github.com/easel/fizeau/internal/productinfo"
)

// ClaudeQuotaSnapshot captures Claude's current-quota headroom as absolute
// token/message counts. It is written to a durable per-user cache by an
// asynchronous capture path and read by foreground routing consumers.
//
// The snapshot is intentionally distinct from the percentage-based
// QuotaSignal: foreground routing needs concrete numbers to reason about
// 5-hour / weekly headroom without invoking PTY capture inline.
type ClaudeQuotaSnapshot struct {
	CapturedAt        time.Time               `json:"captured_at"`
	FiveHourRemaining int                     `json:"five_hour_remaining"`
	FiveHourLimit     int                     `json:"five_hour_limit"`
	WeeklyRemaining   int                     `json:"weekly_remaining"`
	WeeklyLimit       int                     `json:"weekly_limit"`
	Windows           []harnesses.QuotaWindow `json:"windows,omitempty"`
	Source            string                  `json:"source"` // e.g. "pty", "heuristic"
	Account           *harnesses.AccountInfo  `json:"account,omitempty"`
}

// defaultClaudeQuotaStaleAfter is the default maximum age before a cached
// snapshot is considered stale and foreground routing should fall back to
// the safe default.
const DefaultClaudeQuotaStaleAfter = 15 * time.Minute

// claudeQuotaCacheEnv lets tests override the cache file path.
const claudeQuotaCacheEnv = "FIZEAU_CLAUDE_QUOTA_CACHE"

func claudeQuotaCachePathImpl() (string, error) {
	if path := os.Getenv(claudeQuotaCacheEnv); path != "" {
		return path, nil
	}
	if xdg := os.Getenv("XDG_STATE_HOME"); xdg != "" {
		return filepath.Join(xdg, productinfo.ConfigDir, "claude-quota.json"), nil
	}
	home, err := os.UserHomeDir()
	if err != nil {
		return "", err
	}
	return filepath.Join(home, ".local", "state", productinfo.ConfigDir, "claude-quota.json"), nil
}

// WriteClaudeQuota atomically persists a ClaudeQuotaSnapshot to the given
// path. The parent directory is created if necessary. The file is written
// to a sibling .tmp file and renamed into place so readers never observe a
// partially-written snapshot. The final file mode is 0600.
func WriteClaudeQuota(path string, snapshot ClaudeQuotaSnapshot) error {
	if path == "" {
		return fmt.Errorf("claude quota cache path is empty")
	}
	if snapshot.CapturedAt.IsZero() {
		snapshot.CapturedAt = time.Now().UTC()
	} else {
		snapshot.CapturedAt = snapshot.CapturedAt.UTC()
	}

	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return fmt.Errorf("create claude quota cache dir: %w", err)
	}

	data, err := json.MarshalIndent(snapshot, "", "  ")
	if err != nil {
		return fmt.Errorf("marshal claude quota snapshot: %w", err)
	}
	data = append(data, '\n')

	tmpPath := path + ".tmp"
	if err := os.WriteFile(tmpPath, data, 0o600); err != nil {
		return fmt.Errorf("write claude quota cache tmp: %w", err)
	}
	if err := os.Rename(tmpPath, path); err != nil {
		_ = os.Remove(tmpPath)
		return fmt.Errorf("rename claude quota cache: %w", err)
	}
	// Ensure final mode is 0600 in case an older file had a different mode.
	if err := os.Chmod(path, 0o600); err != nil {
		return fmt.Errorf("chmod claude quota cache: %w", err)
	}
	return nil
}

// ReadClaudeQuotaFrom reads the snapshot at the given path. Returns
// (nil, false) if the file does not exist or cannot be decoded. Non-
// existence is NOT an error: foreground callers are expected to fall back
// to a safe default when no snapshot is present.
func ReadClaudeQuotaFrom(path string) (*ClaudeQuotaSnapshot, bool) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, false
	}
	var snap ClaudeQuotaSnapshot
	if err := json.Unmarshal(data, &snap); err != nil {
		return nil, false
	}
	return &snap, true
}

// ReadClaudeQuota reads the cached snapshot from the default location.
// The second return value is false if no snapshot is present or cannot be
// decoded.
//
// Callers SHOULD check snapshot age via ClaudeQuotaSnapshotAge (or
// IsClaudeQuotaFresh) before trusting the values; this function does not
// itself enforce a TTL so that callers can report stale snapshots in
// diagnostic surfaces like `ddx agent doctor --routing`.
func ReadClaudeQuota() (*ClaudeQuotaSnapshot, bool) {
	path, err := claudeQuotaCachePathImpl()
	if err != nil {
		return nil, false
	}
	return ReadClaudeQuotaFrom(path)
}

// ClaudeQuotaSnapshotAge reports the age of a snapshot relative to now.
// A zero or future CapturedAt yields a zero age.
func ClaudeQuotaSnapshotAge(snapshot *ClaudeQuotaSnapshot, now time.Time) time.Duration {
	if snapshot == nil || snapshot.CapturedAt.IsZero() {
		return 0
	}
	age := now.UTC().Sub(snapshot.CapturedAt.UTC())
	if age < 0 {
		return 0
	}
	return age
}

// IsClaudeQuotaFresh reports whether a snapshot exists and is newer than
// staleAfter relative to now. A nil snapshot is never fresh. A zero
// staleAfter falls back to DefaultClaudeQuotaStaleAfter.
func IsClaudeQuotaFresh(snapshot *ClaudeQuotaSnapshot, now time.Time, staleAfter time.Duration) bool {
	if snapshot == nil || snapshot.CapturedAt.IsZero() {
		return false
	}
	if staleAfter <= 0 {
		staleAfter = DefaultClaudeQuotaStaleAfter
	}
	return ClaudeQuotaSnapshotAge(snapshot, now) <= staleAfter
}

// ClaudeQuotaCachePath returns the durable location for the Claude quota cache.
func ClaudeQuotaCachePath() (string, error) {
	return claudeQuotaCachePathImpl()
}

// Internal wrappers for backward compatibility with claude package
func claudeQuotaCachePath() (string, error) {
	return ClaudeQuotaCachePath()
}

func writeClaudeQuota(path string, snapshot ClaudeQuotaSnapshot) error {
	return WriteClaudeQuota(path, snapshot)
}

package harnesses

import (
	"context"
	"encoding/json"
	"errors"
	"time"
)

// AccountInfo captures provider account metadata from local auth files.
type AccountInfo struct {
	Email    string `json:"email,omitempty"`
	PlanType string `json:"plan_type,omitempty"`
	OrgName  string `json:"org_name,omitempty"`
}

// QuotaWindow captures one quota window (e.g. 5h, weekly, model-specific).
type QuotaWindow struct {
	Name          string  `json:"name"`               // e.g. "5h", "7d", "spark"
	LimitID       string  `json:"limit_id,omitempty"` // provider limit_id
	LimitName     string  `json:"limit_name,omitempty"`
	WindowMinutes int     `json:"window_minutes"`
	UsedPercent   float64 `json:"used_percent"`
	ResetsAt      string  `json:"resets_at,omitempty"`      // human-readable
	ResetsAtUnix  int64   `json:"resets_at_unix,omitempty"` // unix timestamp
	State         string  `json:"state"`
}

// QuotaStateFromUsedPercent maps a usage percentage to a quota state string.
func QuotaStateFromUsedPercent(usedPercent int) string {
	if usedPercent >= 95 {
		return "blocked"
	}
	if usedPercent >= 0 {
		return "ok"
	}
	return "unknown"
}

// ModelDiscoverySnapshot captures model and reasoning capability evidence for
// harnesses whose source of truth is a CLI/TUI surface instead of /v1/models.
type ModelDiscoverySnapshot struct {
	CapturedAt      time.Time `json:"captured_at"`
	Models          []string  `json:"models,omitempty"`
	ReasoningLevels []string  `json:"reasoning_levels,omitempty"`
	Source          string    `json:"source"`
	FreshnessWindow string    `json:"freshness_window,omitempty"`
	Detail          string    `json:"detail,omitempty"`
}

// EventType identifies the kind of event a harness emits during execution.
//
// The set is the closed union defined by CONTRACT-003 ("Event JSON shapes"):
// every backend (native + subprocess) emits these identically so the agent
// loop can multiplex them onto a single channel.
type EventType string

const (
	EventTypeTextDelta       EventType = "text_delta"
	EventTypeToolCall        EventType = "tool_call"
	EventTypeToolResult      EventType = "tool_result"
	EventTypeCompaction      EventType = "compaction"
	EventTypeProgress        EventType = "progress"
	EventTypeRoutingDecision EventType = "routing_decision"
	EventTypeStall           EventType = "stall"
	EventTypeFinal           EventType = "final"
)

// Event is the structured event a harness emits during Execute. It mirrors
// the shape defined in CONTRACT-003 §"Event JSON shapes". The Data field is
// a JSON-encoded payload whose schema is determined by Type.
type Event struct {
	Type     EventType         `json:"type"`
	Sequence int64             `json:"sequence"`
	Time     time.Time         `json:"time"`
	Metadata map[string]string `json:"metadata,omitempty"`
	Data     json.RawMessage   `json:"data"`
}

// TextDeltaData is the payload for type=text_delta events.
type TextDeltaData struct {
	Text string `json:"text"`
}

// ToolCallData is the payload for type=tool_call events.
type ToolCallData struct {
	ID    string          `json:"id"`
	Name  string          `json:"name"`
	Input json.RawMessage `json:"input,omitempty"`
}

// ToolResultData is the payload for type=tool_result events.
type ToolResultData struct {
	ID         string `json:"id"`
	Output     string `json:"output,omitempty"`
	Error      string `json:"error,omitempty"`
	DurationMS int64  `json:"duration_ms,omitempty"`
}

// FinalData is the payload for type=final events.
type FinalData struct {
	Status         string            `json:"status"` // success|iteration_limit|failed|stalled|timed_out|cancelled
	ExitCode       int               `json:"exit_code"`
	Error          string            `json:"error,omitempty"`
	FinalText      string            `json:"final_text,omitempty"`
	DurationMS     int64             `json:"duration_ms"`
	Usage          *FinalUsage       `json:"usage,omitempty"`
	Warnings       []FinalWarning    `json:"warnings,omitempty"`
	CostUSD        float64           `json:"cost_usd,omitempty"`
	SessionLogPath string            `json:"session_log_path,omitempty"`
	RoutingActual  *RoutingActual    `json:"routing_actual,omitempty"`
	Reasoning      *ReasoningActual  `json:"reasoning,omitempty"`
	Extra          map[string]string `json:"-"`
}

// FinalUsage carries token totals on a final event. Count fields are pointers
// so unavailable token dimensions are omitted instead of serialized as zero.
// A present pointer to 0 means the harness explicitly reported zero usage.
type FinalUsage struct {
	InputTokens      *int                  `json:"input_tokens,omitempty"`
	OutputTokens     *int                  `json:"output_tokens,omitempty"`
	CacheReadTokens  *int                  `json:"cache_read_tokens,omitempty"`
	CacheWriteTokens *int                  `json:"cache_write_tokens,omitempty"`
	CacheTokens      *int                  `json:"cache_tokens,omitempty"`
	ReasoningTokens  *int                  `json:"reasoning_tokens,omitempty"`
	TotalTokens      *int                  `json:"total_tokens,omitempty"`
	Source           string                `json:"source,omitempty"`
	Fresh            *bool                 `json:"fresh,omitempty"`
	CapturedAt       string                `json:"captured_at,omitempty"`
	Sources          []UsageSourceEvidence `json:"sources,omitempty"`
}

// FinalWarning is normalized metadata about non-fatal final-event issues.
type FinalWarning struct {
	Code    string                `json:"code"`
	Message string                `json:"message,omitempty"`
	Sources []UsageSourceEvidence `json:"sources,omitempty"`
}

// UsageSourceEvidence records one usage source considered by the resolver.
type UsageSourceEvidence struct {
	Source     string            `json:"source"`
	Fresh      *bool             `json:"fresh,omitempty"`
	CapturedAt string            `json:"captured_at,omitempty"`
	Usage      *UsageTokenCounts `json:"usage,omitempty"`
	Warning    string            `json:"warning,omitempty"`
}

// UsageTokenCounts is the normalized token-count vocabulary shared by
// subprocess harnesses and CONTRACT-003 final metadata.
type UsageTokenCounts struct {
	InputTokens      *int `json:"input_tokens,omitempty"`
	OutputTokens     *int `json:"output_tokens,omitempty"`
	CacheReadTokens  *int `json:"cache_read_tokens,omitempty"`
	CacheWriteTokens *int `json:"cache_write_tokens,omitempty"`
	CacheTokens      *int `json:"cache_tokens,omitempty"`
	ReasoningTokens  *int `json:"reasoning_tokens,omitempty"`
	TotalTokens      *int `json:"total_tokens,omitempty"`
}

// Any reports whether at least one token dimension is known.
func (c UsageTokenCounts) Any() bool {
	return c.InputTokens != nil ||
		c.OutputTokens != nil ||
		c.CacheReadTokens != nil ||
		c.CacheWriteTokens != nil ||
		c.CacheTokens != nil ||
		c.ReasoningTokens != nil ||
		c.TotalTokens != nil
}

func IntPtr(v int) *int {
	return &v
}

func BoolPtr(v bool) *bool {
	return &v
}

// RoutingActual captures the resolved fallback chain on a final event.
type RoutingActual struct {
	Harness            string   `json:"harness"`
	Provider           string   `json:"provider,omitempty"`
	ServerInstance     string   `json:"server_instance,omitempty"`
	Model              string   `json:"model"`
	FallbackChainFired []string `json:"fallback_chain_fired,omitempty"`
	FailureClass       string   `json:"failure_class,omitempty"`
	// Power is the catalog-projected power of the actually-dispatched
	// Model. 0 means unknown/exact-pin-only/no catalog entry.
	Power int `json:"power,omitempty"`
}

type ReasoningActual struct {
	Harness            string   `json:"harness,omitempty"`
	RequestedReasoning string   `json:"requested_reasoning,omitempty"`
	ResolvedReasoning  string   `json:"resolved_reasoning,omitempty"`
	Source             string   `json:"source,omitempty"`
	DiscoverySource    string   `json:"discovery_source,omitempty"`
	Reason             string   `json:"reason,omitempty"`
	Warning            string   `json:"warning,omitempty"`
	SupportedReasoning []string `json:"supported_reasoning,omitempty"`
}

// HarnessInfo describes a registered harness. Mirrors the public
// HarnessInfo type defined in CONTRACT-003. Internal callers use this to
// implement the public ListHarnesses surface without re-declaring the shape.
type HarnessInfo struct {
	Name                 string
	Type                 string // "native" | "subprocess"
	Available            bool
	Path                 string
	Error                string
	IsLocal              bool
	IsSubscription       bool
	AutoRoutingEligible  bool
	ExactPinSupport      bool
	DefaultModel         string
	SupportedPermissions []string
	SupportedReasoning   []string
	CostClass            string
}

// ExecuteRequest is the internal request carried into Harness.Execute. It
// is intentionally narrower than the public ExecuteRequest in CONTRACT-003:
// the agent's routing layer is expected to resolve provider/model/reasoning
// /permissions/timeouts before invoking a harness, so the harness sees a
// concrete, ready-to-run request.
type ExecuteRequest struct {
	// Prompt is the resolved user prompt sent to the model.
	Prompt string

	// SystemPrompt is the resolved system prompt; empty means harness default.
	SystemPrompt string

	// Provider is the resolved provider identifier when applicable. May be
	// empty for harnesses that have no provider concept (e.g. claude CLI).
	Provider string

	// Model is the resolved model identifier; empty means harness default.
	Model string

	// WorkDir is the working directory for tool operations. Required when
	// the chosen harness uses tools.
	WorkDir string

	// Permissions is "safe" | "supervised" | "unrestricted". Empty defaults to "safe".
	Permissions string

	// Temperature is the model sampling temperature requested by the caller.
	// Harness adapters may ignore it when their CLI has no equivalent control.
	Temperature float32

	// Seed is the requested sampling seed. Zero means unset/provider chooses.
	// Harness adapters may ignore it when their CLI has no equivalent control.
	Seed int64

	// Reasoning is the normalized public reasoning scalar. Empty/off means no
	// adapter flag should be emitted.
	Reasoning string

package claude

import (
	"fmt"
	"math"
	"os"
	"os/exec"
	"regexp"
	"strconv"
	"strings"
	"time"

	"github.com/easel/fizeau/internal/harnesses"
	"github.com/easel/fizeau/internal/harnesses/anthropic"
)

// stripANSI is delegated to the anthropic package.
func stripANSI(s string) string {
	return anthropic.StripANSI(s)
}

// ReadClaudeQuotaViaTmux starts claude in a detached tmux session, sends /usage,
// captures the pane output, and returns parsed quota windows and account info.
//
// Deprecated: this is a diagnostic-only legacy path. Supported quota probes use
// readClaudeQuotaViaPTY so accepted evidence passes through direct PTY cassettes.
// Returns an error if tmux or claude are not found, or probing times out.
func ReadClaudeQuotaViaTmux(timeout time.Duration) ([]harnesses.QuotaWindow, *harnesses.AccountInfo, error) {
	if _, err := exec.LookPath("tmux"); err != nil {
		return nil, nil, fmt.Errorf("tmux not found in PATH: %w", err)
	}
	if _, err := exec.LookPath("claude"); err != nil {
		return nil, nil, fmt.Errorf("claude not found in PATH: %w", err)
	}
	if timeout <= 0 {
		timeout = 30 * time.Second
	}

	sessName := fmt.Sprintf("ddx-claude-quota-%d", os.Getpid())
	if err := exec.Command("tmux", "new-session", "-d", "-s", sessName, "-x", "220", "-y", "50", "claude").Run(); err != nil {
		return nil, nil, fmt.Errorf("start tmux session: %w", err)
	}
	defer func() { _ = exec.Command("tmux", "kill-session", "-t", sessName).Run() }()

	// Poll until claude shows its interactive prompt (ready state).
	// The prompt "❯" (or "> ") appears once the REPL is initialized.
	deadline := time.Now().Add(timeout)
	ready := false
	for !ready && time.Now().Before(deadline) {
		time.Sleep(500 * time.Millisecond)
		// Bail early if the session has already exited (e.g. non-interactive binary).
		if err := exec.Command("tmux", "has-session", "-t", sessName).Run(); err != nil {
			return nil, nil, fmt.Errorf("claude session exited before initialization")
		}
		out, err := exec.Command("tmux", "capture-pane", "-t", sessName, "-p").Output()
		if err == nil {
			text := stripANSI(string(out))
			// Look for the interactive prompt — appears when REPL is ready.
			if strings.Contains(text, "❯") || strings.Contains(text, "> ") {
				ready = true
			}
		}
	}
	if !ready {
		return nil, nil, fmt.Errorf("timed out waiting for claude to initialize")
	}

	if err := exec.Command("tmux", "send-keys", "-t", sessName, "/usage", "Enter").Run(); err != nil {
		return nil, nil, fmt.Errorf("send /usage: %w", err)
	}

	// Poll until usage data appears (look for "% used" and "Resets").
	var captured string
	for time.Now().Before(deadline) {
		time.Sleep(500 * time.Millisecond)
		out, err := exec.Command("tmux", "capture-pane", "-t", sessName, "-p", "-S", "-100").Output()
		if err == nil {
			text := stripANSI(string(out))
			if strings.Contains(text, "% used") && strings.Contains(strings.ToLower(text), "resets") {
				captured = text
				break
			}
		}
	}
	if captured == "" {
		return nil, nil, fmt.Errorf("timed out waiting for /usage output")
	}

	windows, acct := parseClaudeUsageOutput(captured)
	if len(windows) == 0 {
		return nil, acct, fmt.Errorf("no quota windows found in /usage output")
	}
	return windows, acct, nil
}

var (
	claudeUsedPercentPattern        = regexp.MustCompile(`<?(\d+(?:\.\d+)?)%\s+used`)
	claudePlanTypePattern           = regexp.MustCompile(`(?i)(Claude\s+(?:Max|Pro|Team|Enterprise|Free))`)
	claudeStandalonePlanTypePattern = regexp.MustCompile(`(?i)\b(Max|Pro|Team|Enterprise|Free)\b(?:\s+plan)?`)
)

type claudeUsageSection struct {
	Name       string
	LimitID    string
	WindowMins int
}

var claudeUsageSections = []claudeUsageSection{
	{"Current session", "session", 300},
	{"Current week (all models)", "weekly-all", 10080},
	{"Current week (Sonnet only)", "weekly-sonnet", 10080},
	{"Extra usage", "extra", 0},
}

// parseClaudeUsageOutput parses text captured from a claude /usage pane.
// Returns quota windows and optional account info (plan type from header).
func parseClaudeUsageOutput(text string) ([]harnesses.QuotaWindow, *harnesses.AccountInfo) {
	text = stripANSI(strings.ReplaceAll(text, "\r\n", "\n"))
	lines := strings.Split(text, "\n")

	var acct *harnesses.AccountInfo
	var windows []harnesses.QuotaWindow

	// Extract plan type from header line.
	for _, line := range lines {
		if m := claudePlanTypePattern.FindString(line); m != "" {
			acct = &harnesses.AccountInfo{PlanType: normalizeClaudePlanType(m)}
			break
		}
		if m := claudeStandalonePlanTypePattern.FindStringSubmatch(line); len(m) > 1 {
			acct = &harnesses.AccountInfo{PlanType: normalizeClaudePlanType(m[1])}
			break
		}
	}

	// Walk lines looking for section headers, then harvest % used and Resets.
	for i, line := range lines {
		trimmed := strings.TrimSpace(line)
		trimmedLower := strings.ToLower(trimmed)

		var sec *claudeUsageSection
		for j := range claudeUsageSections {
			if trimmedLower == strings.ToLower(claudeUsageSections[j].Name) {
				sec = &claudeUsageSections[j]
				break
			}
		}
		if sec == nil {
			continue
		}

		// Scan ahead up to 5 lines for "% used" then "Resets".
		var usedPct float64
		var resetsAt string
		found := false

		for j := i + 1; j < len(lines) && j <= i+5; j++ {
			next := strings.TrimSpace(lines[j])
			if !found {
				if m := claudeUsedPercentPattern.FindStringSubmatch(next); m != nil {
					pct, _ := strconv.ParseFloat(m[1], 64)
					usedPct = pct
					found = true
				}
			}
			if found && resetsAt == "" && strings.Contains(strings.ToLower(next), "resets") {
				resetsAt = extractResetsText(next)
			}
			if found && resetsAt != "" {
				break
			}
		}

		if !found {
			continue
		}

		windows = append(windows, harnesses.QuotaWindow{
			Name:          sec.Name,
			LimitID:       sec.LimitID,
			WindowMinutes: sec.WindowMins,
			UsedPercent:   usedPct,
			ResetsAt:      resetsAt,
			State:         harnesses.QuotaStateFromUsedPercent(int(math.Ceil(usedPct))),
		})
	}

	return windows, acct
}

// normalizeClaudePlanType is delegated to the anthropic package.
func normalizeClaudePlanType(plan string) string {
	return anthropic.NormalizeClaudePlanType(plan)
}

// extractResetsText strips the "Resets" prefix from a line.
// Handles: "Resets 4pm (America/New_York)"
//
//	"$200 spent · Resets May 1 (America/New_York)"
func extractResetsText(line string) string {
	lower := strings.ToLower(line)
	idx := strings.Index(lower, "resets")
	if idx < 0 {
		return ""
	}
	return strings.TrimSpace(line[idx+len("resets"):])
}

package claude

import (
	"context"
	"fmt"
	"math"
	"time"

	"github.com/easel/fizeau/internal/harnesses"
	"github.com/easel/fizeau/internal/harnesses/ptyquota"
	"github.com/easel/fizeau/internal/pty/cassette"
	"github.com/easel/fizeau/internal/pty/session"
)

type quotaPTYOptions struct {
	binary      string
	args        []string
	workdir     string
	env         []string
	cassetteDir string
}

type QuotaPTYOption func(*quotaPTYOptions)

func WithQuotaPTYCommand(binary string, args ...string) QuotaPTYOption {
	return func(opts *quotaPTYOptions) {
		opts.binary = binary
		opts.args = append([]string(nil), args...)
	}
}

func WithQuotaPTYWorkdir(workdir string) QuotaPTYOption {
	return func(opts *quotaPTYOptions) {
		opts.workdir = workdir
	}
}

func WithQuotaPTYEnv(env ...string) QuotaPTYOption {
	return func(opts *quotaPTYOptions) {
		opts.env = append([]string(nil), env...)
	}
}

func WithQuotaPTYCassetteDir(dir string) QuotaPTYOption {
	return func(opts *quotaPTYOptions) {
		opts.cassetteDir = dir
	}
}

func readClaudeQuotaViaPTY(timeout time.Duration, opts ...QuotaPTYOption) ([]harnesses.QuotaWindow, *harnesses.AccountInfo, error) {
	windows, account, _, err := captureClaudeQuotaViaPTY(context.Background(), timeout, opts...)
	return windows, account, err
}

func refreshClaudeQuotaViaPTY(timeout time.Duration, opts ...QuotaPTYOption) (claudeQuotaSnapshot, error) {
	windows, account, _, err := captureClaudeQuotaViaPTY(context.Background(), timeout, opts...)
	if err != nil {
		return claudeQuotaSnapshot{}, err
	}
	return claudeQuotaSnapshotFromWindows(windows, account), nil
}

func readClaudeQuotaFromCassette(dir string) ([]harnesses.QuotaWindow, *harnesses.AccountInfo, error) {
	reader, err := cassette.Open(dir)
	if err != nil {
		return nil, nil, err
	}
	text := reader.Final().FinalText
	if text == "" {
		frames := reader.Frames()
		if len(frames) > 0 {
			text = stringsJoinLines(frames[len(frames)-1].Text)
		}
	}
	windows, account := parseClaudeUsageOutput(text)
	if len(windows) == 0 {
		return nil, account, fmt.Errorf("no quota windows found in claude quota cassette")
	}
	if err := validateClaudeQuotaEvidence(windows, account); err != nil {
		return nil, account, fmt.Errorf("incomplete claude quota cassette: %w", err)
	}
	return windows, account, nil
}

func captureClaudeQuotaViaPTY(ctx context.Context, timeout time.Duration, opts ...QuotaPTYOption) ([]harnesses.QuotaWindow, *harnesses.AccountInfo, ptyquota.Result, error) {
	cfg := quotaPTYOptions{binary: "claude"}
	for _, opt := range opts {
		if opt != nil {
			opt(&cfg)
		}
	}
	var windows []harnesses.QuotaWindow
	var account *harnesses.AccountInfo
	result, err := ptyquota.Run(ctx, ptyquota.Config{
		HarnessName:  "claude",
		Binary:       cfg.binary,
		Args:         cfg.args,
		Workdir:      cfg.workdir,
		Env:          cfg.env,
		Command:      "/usage\r",
		ReadyMarkers: []string{"❯", "> "},
		DoneWhen:     claudeUsageComplete,
		Timeout:      timeout,
		Size:         session.Size{Rows: 50, Cols: 220},
		CassetteDir:  cfg.cassetteDir,
		Quota: func(text string) (cassette.QuotaRecord, error) {
			windows, account = parseClaudeUsageOutput(text)
			if len(windows) == 0 {
				return cassette.QuotaRecord{}, fmt.Errorf("no quota windows found in claude /usage output")
			}
			if err := validateClaudeQuotaEvidence(windows, account); err != nil {
				return cassette.QuotaRecord{}, fmt.Errorf("incomplete claude /usage output: %w", err)
			}
			return quotaRecord(windows, map[string]any{"plan_type": accountPlan(account)}), nil
		},
	})
	if err != nil {
		return nil, nil, result, err
	}
	if len(windows) == 0 {
		windows, account = parseClaudeUsageOutput(result.Text)
	}
	if len(windows) == 0 {
		return nil, account, result, fmt.Errorf("no quota windows found in claude /usage output")
	}
	if err := validateClaudeQuotaEvidence(windows, account); err != nil {
		return nil, account, result, fmt.Errorf("incomplete claude /usage output: %w", err)
	}
	return windows, account, result, nil
}

func claudeQuotaSnapshotFromWindows(windows []harnesses.QuotaWindow, account *harnesses.AccountInfo) claudeQuotaSnapshot {
	fiveHourUsed := usedPercentFor(windows, "session")
	weeklyUsed := usedPercentFor(windows, "weekly-all")
	if weeklyUsed < 0 {
		weeklyUsed = usedPercentFor(windows, "weekly-sonnet")
	}
	return claudeQuotaSnapshot{
		CapturedAt:        time.Now().UTC(),
		FiveHourLimit:     100,
		FiveHourRemaining: remainingPercent(fiveHourUsed),
		WeeklyLimit:       100,
		WeeklyRemaining:   remainingPercent(weeklyUsed),
		Windows:           append([]harnesses.QuotaWindow(nil), windows...),
		Source:            "pty",
		Account:           account,
	}
}

func usedPercentFor(windows []harnesses.QuotaWindow, limitID string) float64 {
	for _, window := range windows {
		if window.LimitID == limitID {
			return window.UsedPercent
		}
	}
	return -1
}

func hasQuotaWindow(windows []harnesses.QuotaWindow, limitID string) bool {
	return usedPercentFor(windows, limitID) >= 0
}

func claudeUsageComplete(text string) bool {
	windows, _ := parseClaudeUsageOutput(text)
	return hasQuotaWindow(windows, "session") && (hasQuotaWindow(windows, "weekly-all") || hasQuotaWindow(windows, "weekly-sonnet"))
}

func validateClaudeQuotaEvidence(windows []harnesses.QuotaWindow, account *harnesses.AccountInfo) error {
	if accountPlan(account) == "" {
		return fmt.Errorf("missing account plan")
	}
	if !hasQuotaWindow(windows, "session") {
		return fmt.Errorf("missing session window")
	}
	if !hasQuotaWindow(windows, "weekly-all") && !hasQuotaWindow(windows, "weekly-sonnet") {
		return fmt.Errorf("missing weekly window")
	}
	return nil
}

func remainingPercent(used float64) int {
	if used < 0 {
		return 0
	}
	remaining := int(math.Round(100 - used))
	if remaining < 0 {
		return 0
	}
	if remaining > 100 {
		return 100
	}
	return remaining
}

func quotaRecord(windows []harnesses.QuotaWindow, metadata map[string]any) cassette.QuotaRecord {
	records := make([]map[string]any, 0, len(windows))
	for _, window := range windows {
		records = append(records, map[string]any{
			"name":           window.Name,
			"limit_id":       window.LimitID,
			"window_minutes": window.WindowMinutes,
			"used_percent":   window.UsedPercent,
			"resets_at":      window.ResetsAt,
			"state":          window.State,
		})
	}
	accountClass, _ := metadata["plan_type"].(string)
	return cassette.QuotaRecord{
		Source:            "pty",
		Status:            string(ptyquota.StatusOK),
		CapturedAt:        time.Now().UTC().Format(time.RFC3339),
		FreshnessWindow:   defaultClaudeQuotaStaleAfter.String(),
		StalenessBehavior: "stale quota evidence keeps Claude out of automatic routing and is treated as limited",
		AccountClass:      accountClass,
		Windows:           records,
		Metadata:          metadata,
	}
}

func accountPlan(account *harnesses.AccountInfo) string {
	if account == nil {
		return ""
	}
	return account.PlanType
}

func stringsJoinLines(lines []string) string {
	out := ""
	for i, line := range lines {
		if i > 0 {
			out += "\n"
		}
		out += line
	}
	return out
}

	// Timeout is the wall-clock cap for the entire request. 0 disables.
	Timeout time.Duration

	// IdleTimeout is the streaming-quiet cap. 0 uses harness default.
	IdleTimeout time.Duration

	// SessionLogDir overrides the per-run session-log directory; harness
	// uses this to direct progress traces into a per-bundle evidence dir.
	SessionLogDir string

	// SessionID is a stable identifier for the run, used in progress log
	// filenames and event metadata. Empty means the harness generates one.
	SessionID string

	// Metadata is echoed back into Event.Metadata (e.g. bead_id, attempt_id).
	Metadata map[string]string
}

// Harness is the internal contract every harness implementation in
// internal/harnesses/<name> satisfies. It is the minimal surface the agent
// dispatcher needs to route a resolved request into a backend.
//
// A Harness is responsible for emitting events on the returned channel until
// execution completes; the channel MUST be closed after the final event so
// downstream consumers can detect end-of-stream. The final event is always
// of type EventTypeFinal.
type Harness interface {
	// Info returns identity + capability metadata for this harness.
	Info() HarnessInfo

	// HealthCheck triggers a fresh probe (binary present, auth ok, etc.)
	// and returns nil if the harness is ready to execute.
	HealthCheck(ctx context.Context) error

	// Execute runs one resolved request. Events stream on the returned
	// channel; a single final event closes the stream. The first error
	// return is reserved for setup failures (binary missing, etc.) — once
	// the channel is returned, all per-run failures are reported via a
	// final event with Status != "success".
	Execute(ctx context.Context, req ExecuteRequest) (<-chan Event, error)
}

// QuotaStateValue is the normalized state enumeration consumed by
// CONTRACT-004 sub-interfaces. Only QuotaOK and QuotaStale carry
// routing-usable signal; other values MUST NOT result in
// RoutingPreferenceAvailable.
type QuotaStateValue string

const (
	QuotaOK              QuotaStateValue = "ok"
	QuotaStale           QuotaStateValue = "stale"
	QuotaBlocked         QuotaStateValue = "blocked"
	QuotaUnavailable     QuotaStateValue = "unavailable"
	QuotaUnauthenticated QuotaStateValue = "unauthenticated"
	QuotaUnknown         QuotaStateValue = "unknown"
)

// RoutingPreference is the routing layer's consumable signal indicating
// whether a harness should be preferred given its current quota evidence.
// It is an internal routing signal — never projected into the public
// CONTRACT-003 surface.
type RoutingPreference int

const (
	RoutingPreferenceUnknown RoutingPreference = iota
	RoutingPreferenceAvailable
	RoutingPreferenceBlocked
)

// QuotaStatus is the universal quota report defined by CONTRACT-004.
// Each harness's private snapshot type projects into this; the private
// snapshot is never exposed across package boundaries.
type QuotaStatus struct {
	// Source identifies how the underlying evidence was captured:
	// "pty", "cache", "session-token-count", "cli", "api".
	Source string

	// CapturedAt is when the underlying evidence was observed (not when
	// this status struct was assembled).
	CapturedAt time.Time

	// Fresh reports whether CapturedAt is within QuotaFreshness() at the
	// time of the call.
	Fresh bool

	// Age is now - CapturedAt at the time of the call.
	Age time.Duration

	// State is the normalized state. Only QuotaOK and QuotaStale carry
	// routing-usable signal.
	State QuotaStateValue

	// Windows captures per-window evidence (5h, weekly, tier-specific).
	// Authoritative for any structured fact the routing layer or
	// operator surfaces consume — including tier breakdowns.
	Windows []QuotaWindow

	// Account is the account/plan/auth evidence captured alongside
	// quota. Nil when the harness has no concept of account or when
	// account evidence is delivered through AccountHarness only.
	Account *AccountSnapshot

	// RoutingPreference indicates whether the routing layer should
	// prefer this harness given the current evidence.
	RoutingPreference RoutingPreference

	// Reason is a short human-readable explanation of State and
	// RoutingPreference — surfaced in operator views and routing logs.
	Reason string

	// Detail is harness-specific opaque metadata for diagnostic display
	// only. Service code MAY surface it verbatim in operator views;
	// service code MUST NOT branch on its keys or values for routing
	// decisions.
	Detail map[string]string
}

// AccountSnapshot is the universal account/auth report defined by
// CONTRACT-004. Projects onto the public AccountStatus type defined in
// CONTRACT-003.
type AccountSnapshot struct {
	Authenticated   bool
	Unauthenticated bool
	Email           string
	PlanType        string
	OrgName         string
	Source          string // file path, env var name, "cache", "cli"
	CapturedAt      time.Time
	Fresh           bool
	Detail          string // free-form diagnostic detail
}

// ErrAliasNotResolvable is returned by ModelDiscoveryHarness.ResolveModelAlias
// when the requested family is not recognized or the supplied discovery
// snapshot has no matching concrete model.
var ErrAliasNotResolvable = errors.New("model alias not resolvable from snapshot")

// ErrModelDiscoveryEvidenceMissing is returned by ModelDiscoveryHarness.DefaultModelSnapshot
// when live evidence cannot be obtained (PTY failure, parse failure, etc.) and
// no static fallback is available per the no-static-fallback principle.
var ErrModelDiscoveryEvidenceMissing = errors.New("model discovery evidence missing")

// QuotaHarness is implemented by harnesses that own a subscription or
// quota window. See CONTRACT-004 for the full normative contract.
type QuotaHarness interface {
	Harness

	// QuotaStatus returns the current quota state from the harness's
	// owned cache, with Fresh/Age computed against now. MUST be cheap
	// (no live probe) and safe to call on every routing decision.
	// Absence of evidence is reported via State=QuotaUnavailable on a
	// valid QuotaStatus value; the error return is reserved for call
	// failure (ctx cancelled, IO failure, lock acquisition failure).
	QuotaStatus(ctx context.Context, now time.Time) (QuotaStatus, error)

	// RefreshQuota drives the harness's live probe, persists the
	// result through the harness's owned cache, and returns the
	// resulting status. Single-flight per harness instance via the
	// harness's cache lock; concurrent callers block. Probe failure
	// is reported as a QuotaStatus with State=QuotaUnavailable (or
	// QuotaUnauthenticated for auth-related failures), not as an
	// error. The error return is reserved for call failure.
	RefreshQuota(ctx context.Context) (QuotaStatus, error)

	// QuotaFreshness returns the harness's freshness window (e.g. 15m).
	// Constant for the harness; cheap to call.
	QuotaFreshness() time.Duration

	// SupportedLimitIDs returns the harness's stable set of emitted
	// Windows[].LimitID values. Constant for the harness; the
	// conformance suite reads this value to verify that emitted
	// Windows[].LimitID strings are a subset of this set. Empty
	// slice is allowed for harnesses that emit no windows.
	SupportedLimitIDs() []string
}

// AccountHarness is implemented by harnesses that expose authentication
// or account state independent of quota. See CONTRACT-004 for the full
// normative contract.
type AccountHarness interface {
	Harness

	// AccountStatus returns the harness's current account/auth state.
	// Cheap; reads cached evidence only. Absence of evidence is
	// reported via AccountSnapshot fields on a valid snapshot; the
	// error return is reserved for call failure.
	AccountStatus(ctx context.Context, now time.Time) (AccountSnapshot, error)

	// RefreshAccount drives the harness's account probe and persists
	// the result. Single-flight per harness instance; concurrent
	// callers block. Probe failure is reported via AccountSnapshot
	// fields, not as an error.
	RefreshAccount(ctx context.Context) (AccountSnapshot, error)

	// AccountFreshness returns the harness's account freshness window
	// (e.g. 7 days for gemini). Constant for the harness; cheap.
	AccountFreshness() time.Duration
}

// ModelDiscoveryHarness is implemented by harnesses whose model surface
// extends beyond a single Info().DefaultModel — i.e. they support family
// aliases (sonnet, gpt, gemini) that resolve through discovery evidence.
// See CONTRACT-004 for the full normative contract.
type ModelDiscoveryHarness interface {
	Harness

	// DefaultModelSnapshot returns the harness's seed/fallback
	// discovery snapshot. Used to bootstrap the catalog before the
	// first live refresh lands. Per the no-static-fallback principle,
	// returns ErrModelDiscoveryEvidenceMissing when live evidence cannot
	// be obtained; never returns a cached or literal fallback.
	DefaultModelSnapshot() (ModelDiscoverySnapshot, error)

	// ResolveModelAlias maps a family-style requested model to a
	// concrete model ID using the provided discovery snapshot.
	// Returns ErrAliasNotResolvable if the family is not recognized
	// or the snapshot has no matching concrete model.
	ResolveModelAlias(family string, snapshot ModelDiscoverySnapshot) (string, error)

	// SupportedAliases returns the harness's stable set of family
	// aliases ResolveModelAlias recognizes. Constant for the harness;
	// the conformance suite uses this value to verify
	// ResolveModelAlias covers each documented family (positive path)
	// and rejects out-of-set families with ErrAliasNotResolvable
	// (negative path). Empty slice is allowed for harnesses that
	// recognize no family aliases.
	SupportedAliases() []string
}

package anthropic

import (
	"regexp"
	"strings"
)

var ansiPattern = regexp.MustCompile(`\x1b(?:\[[0-9;?]*[a-zA-Z]|[^[])`)

// StripANSI removes ANSI escape sequences from a string.
func StripANSI(s string) string {
	return ansiPattern.ReplaceAllString(s, "")
}

// NormalizeClaudePlanType normalizes a plan type string to a canonical form.
// Handles: "Claude Max", "Max", "Pro", etc.
func NormalizeClaudePlanType(plan string) string {
	plan = strings.TrimSpace(plan)
	if plan == "" {
		return ""
	}
	if strings.HasPrefix(strings.ToLower(plan), "claude ") {
		return plan
	}
	return "Claude " + plan
}

package anthropic

import (
