func Test_quotaRecordClaudePTY(t *testing.T) {
	if os.Getenv("FIZEAU_HARNESS_RECORD") != "1" {
		t.Skip("set FIZEAU_HARNESS_RECORD=1 to refresh authenticated claude quota cassette")
	}
	dir := filepath.Join(recordBaseDir(t), "claude", "quota")
	windows, account, err := readClaudeQuotaViaPTY(45*time.Second, WithQuotaPTYCassetteDir(dir))
	if err != nil {
		assertNoAcceptedCassette(t, dir)
		t.Fatalf("record claude quota via PTY: %v", err)
	}
	require.NotEmpty(t, windows)
	if account != nil {
		t.Logf("recorded claude quota for account class %q", account.PlanType)
	}
	reader, err := cassette.Open(dir)
	require.NoError(t, err)
	require.NotNil(t, reader.Quota())
}

func Test_modelDiscoveryRecordClaudePTY(t *testing.T) {
	if os.Getenv("FIZEAU_HARNESS_RECORD") != "1" {
		t.Skip("set FIZEAU_HARNESS_RECORD=1 to refresh authenticated claude model cassette")
	}
	dir := filepath.Join(recordBaseDir(t), "claude", "models")
	snapshot, err := ReadClaudeModelDiscoveryViaPTY(45*time.Second, WithQuotaPTYCassetteDir(dir))
	if err != nil {
		assertNoAcceptedCassette(t, dir)
		t.Fatalf("record claude model discovery via PTY: %v", err)
	}
	require.NotEmpty(t, snapshot.Models)
	require.NotEmpty(t, snapshot.ReasoningLevels)
	reader, err := cassette.Open(dir)
	require.NoError(t, err)
	require.NotNil(t, reader.Discovery())
}

func recordBaseDir(t *testing.T) string {
	t.Helper()
	if dir := os.Getenv("FIZEAU_HARNESS_CASSETTE_DIR"); dir != "" {
		return dir
	}
	if dir := os.Getenv("FIZEAU_HARNESS_RECORD_DIR"); dir != "" {
		return dir
	}
	return t.TempDir()
}

func assertNoAcceptedCassette(t *testing.T, dir string) {
	t.Helper()
	_, err := os.Stat(filepath.Join(dir, cassette.ManifestFile))
	if err == nil {
		t.Fatalf("failed quota record left accepted cassette evidence at %s", dir)
	}
	require.True(t, errors.Is(err, os.ErrNotExist), "unexpected cassette stat error")
}

//go:build !windows

package session

import (
	"context"
	"errors"
	"io"
	"os"
	"os/exec"
	"syscall"
	"time"

	"github.com/creack/pty"
)

// Start launches command under a direct PTY with argv, workdir, env, and size.
// Cancellation is controlled by ctx and WithTimeout.
func Start(ctx context.Context, command string, args []string, workdir string, env []string, size Size, opts ...Option) (*Session, error) {
	if command == "" {
		return nil, errors.New("command is required")
	}
	if err := validateSize(size); err != nil {
		return nil, err
	}
	cfg := applyOptions(opts)
	if ctx == nil {
		ctx = context.Background()
	}
	var timeoutCancel context.CancelFunc
	if cfg.Timeout > 0 {
		ctx, timeoutCancel = context.WithTimeout(ctx, cfg.Timeout)
	}
	runCtx, runCancel := context.WithCancel(ctx)
	cancel := func() {
		runCancel()
		if timeoutCancel != nil {
			timeoutCancel()
		}
	}
	// #nosec G204 -- command and args are explicit PTY session API inputs;
	// exec.Command does not invoke a shell.
	cmd := exec.Command(command, args...)
	cmd.Dir = workdir
	if len(env) > 0 {
		cmd.Env = append(os.Environ(), env...)
	}

	ptmx, err := pty.StartWithSize(cmd, &pty.Winsize{Rows: size.Rows, Cols: size.Cols})
	if err != nil {
		cancel()
		return nil, err
	}

	s := &Session{
		start:    cfg.Clock.Now(),
		clock:    cfg.Clock,
		size:     size,
		cancel:   cancel,
		output:   make(chan OutputChunk, 128),
		events:   make(chan Event, 256),
		waitDone: make(chan struct{}),
		readDone: make(chan struct{}),
	}
	s.impl = &unixImpl{cmd: cmd, file: ptmx}

	go s.readLoop(ptmx, cfg.BufferSize)
	go func() {
		select {
		case <-runCtx.Done():
			select {
			case <-s.waitDone:
				return
			default:
			}
			_ = s.Kill()
		case <-s.waitDone:
			return
		}
	}()
	go func() {
		<-s.waitDone
		<-s.readDone
		s.closeEvents()
	}()
	return s, nil
}

func (s *Session) readLoop(r io.Reader, bufferSize int) {
	defer close(s.readDone)
	defer close(s.output)
	buf := make([]byte, bufferSize)
	for {
		n, err := r.Read(buf)
		if n > 0 {
			s.emitOutput(buf[:n], nil, false)
		}
		if err != nil {
			if errors.Is(err, io.EOF) || errors.Is(err, syscall.EIO) {
				s.emitOutput(nil, nil, true)
			} else {
				s.emitOutput(nil, err, true)
			}
			return
		}
	}
}

type unixImpl struct {
	cmd  *exec.Cmd
	file *os.File
}

func (u *unixImpl) write(b []byte) (int, error) { return u.file.Write(b) }

func (u *unixImpl) resize(size Size) error {
	return pty.Setsize(u.file, &pty.Winsize{Rows: size.Rows, Cols: size.Cols})
}

func (u *unixImpl) close() error { return u.file.Close() }

func (u *unixImpl) kill() error {
	if u.cmd.Process == nil {
		return nil
	}
	pgid, err := syscall.Getpgid(u.cmd.Process.Pid)
	if err == nil {
		if killProcessGroup(pgid, syscall.SIGTERM) {
			time.Sleep(100 * time.Millisecond)
		}
		_ = killProcessGroup(pgid, syscall.SIGKILL)
		return nil
	}
	return u.cmd.Process.Kill()
}

func killProcessGroup(pgid int, sig syscall.Signal) bool {
	if pgid <= 0 {
		return false
	}
	err := syscall.Kill(-pgid, sig)
	return err == nil || errors.Is(err, syscall.ESRCH)
}

func (u *unixImpl) wait() ExitStatus {
	err := u.cmd.Wait()
	if err == nil {
		return ExitStatus{Code: 0, Exited: true}
	}
	status := ExitStatus{Code: -1, Err: err}
	var exitErr *exec.ExitError
	if errors.As(err, &exitErr) {
		if ws, ok := exitErr.Sys().(syscall.WaitStatus); ok {
			status.Code = ws.ExitStatus()
			status.Exited = ws.Exited()
			status.Signaled = ws.Signaled()
			if status.Signaled {
				status.Signal = ws.Signal().String()
			}
		} else {
			status.Code = exitErr.ExitCode()
		}
		return status
	}
	return status
}

// Package session owns direct PTY process lifecycle and timed raw/input events.
//
// See internal/pty/doc.go for the governing ADR/SPIKE citations that authorize
// this package boundary.
package session

import (
	"context"
	"errors"
	"fmt"
	"sync"
	"time"
)

// Size is a terminal rows/columns pair.
type Size struct {
	Rows uint16
	Cols uint16
}

// OutputChunk is one timed raw PTY read.
type OutputChunk struct {
	Seq       uint64
	At        time.Time
	TMS       int64
	Offset    int64
	Bytes     []byte
	ReadError error
	EOF       bool
}

// EventKind identifies cassette-facing session events.
type EventKind string

const (
	EventOutput EventKind = "output"
	EventInput  EventKind = "input"
	EventResize EventKind = "resize"
	EventSignal EventKind = "signal"
	EventExit   EventKind = "exit"
)

// Event is the narrow timed event shape consumed by follow-on cassette code.
type Event struct {
	Seq    uint64
	Kind   EventKind
	At     time.Time
	TMS    int64
	Offset int64
	Bytes  []byte
	Key    Key
	Size   Size
	Signal string
	Exit   *ExitStatus
	Err    error
}

// Key names common terminal inputs.
type Key string

const (
	KeyEnter     Key = "enter"
	KeyTab       Key = "tab"
	KeyEscape    Key = "escape"
	KeyBackspace Key = "backspace"
	KeyUp        Key = "up"
	KeyDown      Key = "down"
	KeyRight     Key = "right"
	KeyLeft      Key = "left"
)

// CtrlKey returns a letter control-key input such as Ctrl-C.
func CtrlKey(r rune) Key {
	if r >= 'A' && r <= 'Z' {
		r += 'a' - 'A'
	}
	return Key(fmt.Sprintf("ctrl-%c", r))
}

// KeyBytes encodes a supported key as terminal input bytes.
func KeyBytes(k Key) ([]byte, error) {
	switch k {
	case KeyEnter:
		return []byte{'\r'}, nil
	case KeyTab:
		return []byte{'\t'}, nil
	case KeyEscape:
		return []byte{0x1b}, nil
	case KeyBackspace:
		return []byte{0x7f}, nil
	case KeyUp:
		return []byte("\x1b[A"), nil
	case KeyDown:
		return []byte("\x1b[B"), nil
	case KeyRight:
		return []byte("\x1b[C"), nil
	case KeyLeft:
		return []byte("\x1b[D"), nil
	}
	var r rune
	if _, err := fmt.Sscanf(string(k), "ctrl-%c", &r); err == nil {
		if r >= 'A' && r <= 'Z' {
			r += 'a' - 'A'
		}
		if r >= 'a' && r <= 'z' {
			return []byte{byte(r - 'a' + 1)}, nil
		}
	}
	return nil, fmt.Errorf("unsupported key %q", k)
}

// Clock lets tests inject deterministic timestamps.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// Option configures Start.
type Option func(*Config)

// Config controls session startup.
type Config struct {
	Clock      Clock
	Timeout    time.Duration
	BufferSize int
}

// WithClock injects a deterministic clock.
func WithClock(clock Clock) Option {
	return func(cfg *Config) {
		cfg.Clock = clock
	}
}

// WithTimeout applies a wall-clock timeout in addition to ctx cancellation.
func WithTimeout(timeout time.Duration) Option {
	return func(cfg *Config) {
		cfg.Timeout = timeout
	}
}

// WithBufferSize changes the raw read buffer size.
func WithBufferSize(size int) Option {
	return func(cfg *Config) {
		cfg.BufferSize = size
	}
}

func applyOptions(opts []Option) Config {
	cfg := Config{Clock: realClock{}, BufferSize: 32 * 1024}
	for _, opt := range opts {
		opt(&cfg)
	}
	if cfg.Clock == nil {
		cfg.Clock = realClock{}
	}
	if cfg.BufferSize <= 0 {
		cfg.BufferSize = 32 * 1024
	}
	return cfg
}

// ExitStatus describes process termination.
type ExitStatus struct {
	Code     int
	Signal   string
	Exited   bool
	Signaled bool
	Err      error
}

// Session is a running PTY-backed process.
type Session struct {
	start  time.Time
	clock  Clock
	size   Size
	cancel context.CancelFunc

	mu       sync.Mutex
	seq      uint64
	offset   int64
	closed   bool
	waitOnce sync.Once
	waitDone chan struct{}
	waitStat ExitStatus
	readDone chan struct{}

	output       chan OutputChunk
	events       chan Event
	eventsMu     sync.Mutex
	eventsClosed bool

	impl sessionImpl
}

type sessionImpl interface {
	write([]byte) (int, error)
	resize(Size) error
	close() error
	kill() error
	wait() ExitStatus
}

var (
	// ErrClosed is returned when writing to a closed session.
	ErrClosed = errors.New("pty session closed")
)

// Output returns timed raw PTY chunks. The channel closes after the read loop
// reaches EOF or Close/Kill tears the PTY down.
func (s *Session) Output() <-chan OutputChunk { return s.output }

// Events returns timed input/output/resize/signal/exit events.
func (s *Session) Events() <-chan Event { return s.events }

// Size returns the last requested terminal size.
func (s *Session) Size() Size {

