+func (h *Harness) probeQuotaStatus(ctx context.Context, now time.Time) (harnesses.QuotaStatus, error) {
+	if err := ctx.Err(); err != nil {
+		return harnesses.QuotaStatus{}, err
+	}
+	text, err := h.captureSurface(ctx, "/quota-observation")
+	status := harnesses.QuotaStatus{
+		Source:            "pty",
+		CapturedAt:        now.UTC(),
+		Fresh:             true,
+		Age:               0,
+		State:             harnesses.QuotaUnavailable,
+		RoutingPreference: harnesses.RoutingPreferenceUnknown,
+	}
+	if err != nil {
+		status.Reason = err.Error()
+		return status, nil
+	}
+	windows, account, parseErr := anthropic.ParseClaudeTUIQuotaObservationOutput(text)
+	if parseErr != nil {
+		status.Reason = parseErr.Error()
+		return status, nil
+	}
+	status.Windows = append([]harnesses.QuotaWindow(nil), windows...)
+	if account != nil {
+		status.Account = &harnesses.AccountSnapshot{
+			Authenticated: strings.TrimSpace(account.Email) != "" || strings.TrimSpace(account.PlanType) != "" || strings.TrimSpace(account.OrgName) != "",
+			Email:         account.Email,
+			PlanType:      account.PlanType,
+			OrgName:       account.OrgName,
+			Source:        "pty",
+			CapturedAt:    now.UTC(),
+			Fresh:         true,
+		}
+	}
+	status.State = quotaStateFromWindows(windows)
+	switch status.State {
+	case harnesses.QuotaOK:
+		status.RoutingPreference = harnesses.RoutingPreferenceAvailable
+	case harnesses.QuotaBlocked:
+		status.RoutingPreference = harnesses.RoutingPreferenceBlocked
+	default:
+		status.RoutingPreference = harnesses.RoutingPreferenceUnknown
+	}
+	status.Reason = "observed quota-observation surface"
+	return status, nil
+}
