+func (h *Harness) captureSurface(ctx context.Context, command string) (string, error) {
+	binary, ok := h.binaryPath()
+	if !ok {
+		return "", fmt.Errorf("%s not found in PATH", binary)
+	}
+	timeout := 30 * time.Second
+	if deadline, ok := ctx.Deadline(); ok {
+		if remaining := time.Until(deadline); remaining > 0 && remaining < timeout {
+			timeout = remaining
+		}
+	}
+	result, err := ptyquota.Run(ctx, ptyquota.Config{
+		HarnessName:  "claude-tui",
+		Binary:       binary,
+		Command:      command + "\r",
+		ReadyMarkers: []string{"❯", "> "},
+		DoneWhen: func(text string) bool {
+			switch command {
+			case "/auth-status":
+				return anthropic.ClaudeTUIAuthStatusComplete(text)
+			case "/quota-observation":
+				return anthropic.ClaudeTUIQuotaObservationComplete(text)
+			default:
+				return strings.TrimSpace(text) != ""
+			}
+		},
+		Timeout: timeout,
+		Size:    session.Size{Rows: 50, Cols: 220},
+	})
+	if err != nil {
+		return result.Text, err
+	}
+	if strings.TrimSpace(result.Text) == "" {
+		return "", fmt.Errorf("no output captured from %s", command)
+	}
+	return result.Text, nil
+}
+
+func quotaStateFromWindows(windows []harnesses.QuotaWindow) harnesses.QuotaStateValue {
+	if len(windows) == 0 {
+		return harnesses.QuotaUnavailable
+	}
+	maxUsed := 0.0
+	for _, window := range windows {
+		if strings.EqualFold(window.State, "blocked") {
+			return harnesses.QuotaBlocked
+		}
+		if window.UsedPercent > maxUsed {
+			maxUsed = window.UsedPercent
+		}
+	}
+	if maxUsed >= 95 {
+		return harnesses.QuotaBlocked
+	}
+	return harnesses.QuotaOK
+}
